const customerId = String($json.customer_id ?? '').trim().toUpperCase();
if (!/^[A-Z0-9][A-Z0-9_-]{1,63}$/.test(customerId)) {
  throw new Error('customer_id is required and invalid');
}
const requested = Number($json.limit ?? 10);
const limit = Math.min(Math.max(Number.isFinite(requested) ? Math.floor(requested) : 10, 1), 20);
return { json: { customer_id: customerId, limit, started_at_ms: Date.now() } };

parameters.query:
select
  exists(select 1 from public.customers c where c.customer_id = $1::text) as customer_found,
  coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'event_code', e.event_code,
        'event_type', e.event_type,
        'details', e.details,
        'occurred_at', e.occurred_at
      ) order by e.occurred_at desc
    )
    from (
      select event_code, event_type, details, occurred_at
      from public.account_events
      where customer_id = $1::text
      order by occurred_at desc
      limit $2::integer
    ) e
  ), '[]'::jsonb) as events;

parameters.jsCode:
const input = $('Validate Event Query').first().json;
const row = $input.first().json ?? {};
let events = row.events ?? [];
if (typeof events === 'string') {
  try { events = JSON.parse(events); } catch { events = []; }
}
if (!Array.isArray(events)) events = [];

return [{ json: {
  found: Boolean(row.customer_found),
  customer_id: input.customer_id,
  event_count: events.length,
  events,
  latency_ms: Date.now() - input.started_at_ms
} }];
